pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory users, uint256[] memory amounts) public {
        vm.assume(users.length == amounts.length);
        vm.assume(users.length > 0 && users.length <= 10);
        uint256 expectedTotal = 0;
        for (uint i = 0; i < users.length; i++) {
            vm.deal(users[i], amounts[i]);
            vm.prank(users[i]);
            c.deposit{value: amounts[i]}();
            expectedTotal += amounts[i];
        }
        // Only the public balance getter is available
        uint256 actualBalance = c.balance();
        assertTrue(actualBalance == expectedTotal);
    }
}

