pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address user1, address user2, uint256 amount1, uint256 amount2) public {
        vm.assume(user1 != address(0) && user2 != address(0));
        vm.assume(user1 != user2);
        uint256 boundedAmount1 = bound(amount1, 1, 1000 ether);
        uint256 boundedAmount2 = bound(amount2, 1, 1000 ether);

        vm.deal(user1, boundedAmount1);
        vm.deal(user2, boundedAmount2);

        vm.prank(user1);
        c.deposit{value: boundedAmount1}();
        vm.prank(user2);
        c.deposit{value: boundedAmount2}();

        uint256 totalCredits = c.credit(user1) + c.credit(user2);
        assertTrue(c.balance(address(c)) == totalCredits);
    }
}
